const response = $input.first().json;
const servicos = Array.isArray(response.data) ? response.data : [];
const firstDefined = (...values) => values.find((value) => value !== undefined);
const asArray = (value) => Array.isArray(value) ? value : [];

return servicos.map((servico) => {
  const id = firstDefined(servico.id, servico.id_tp_solicitacao);
  const nome = firstDefined(servico.nome, servico.title);
  const descricao = firstDefined(servico.descricao, servico.description);
  const msgPedido = firstDefined(servico.msg_pedido, servico.msgPedido);
  const quemRaw = asArray(firstDefined(servico.quem_deve_solicitar, servico.quemDeveSolicitar, []));
  const onboardingRaw = asArray(firstDefined(servico.tipos_onboarding, servico.tiposOnboarding, []));
  const representantesRaw = asArray(firstDefined(servico.dm_tp_representante, servico.dmTpRepresentante, []));

  const title = nome || `Servico ${id}`;
  const description = descricao || msgPedido || title;

  const dmTpRepresentante = representantesRaw.length > 0
    ? [...new Set(representantesRaw.filter(Boolean))]
    : [...new Set(quemRaw.map((item) => firstDefined(item.dm_tp_representante, item.dmTpRepresentante)).filter(Boolean))];

  const quemDeveSolicitar = quemRaw
    .filter((item) => firstDefined(item.dm_objecto, item.dmObjecto))
    .map((item) => ({
      dm_objecto: firstDefined(item.dm_objecto, item.dmObjecto),
      dm_objecto_desc: firstDefined(item.dm_objecto_desc, item.dmObjectoDesc) ?? null
    }));

  const tiposOnboarding = onboardingRaw
    .filter((item) => firstDefined(item.dm_tipo_onboarding, item.dmTipoOnboarding))
    .map((item) => ({
      id_tipo_onboarding: firstDefined(item.id_tipo_onboarding, item.id) ?? null,
      dm_tipo_onboarding: firstDefined(item.dm_tipo_onboarding, item.dmTipoOnboarding),
      dm_tipo_onboarding_desc: firstDefined(item.dm_tipo_onboarding_desc, item.dmTipoOnboardingDesc) ?? null,
      ordem: firstDefined(item.ordem) == null ? null : Number(item.ordem)
    }));

  const data = {
    service_id: servico.id,
    title,
    description,
    icon: null,
    content: description,
    requirements: [],
    highlighted: false,
    button_text: 'Ver +',
    dm_tipo_solicitacao: firstDefined(servico.dm_tipo_solicitacao, servico.dmTipoSolicitacao) ?? null,
    dm_tipo_solicitacao_desc: firstDefined(servico.dm_tipo_solicitacao_desc, servico.dmTipoSolicitacaoDesc) ?? null,
    dm_tp_representante: dmTpRepresentante,
    dm_categoria: firstDefined(servico.dm_categoria, servico.dmCategoria) ?? null,
    dm_categoria_desc: firstDefined(servico.dm_categoria_desc, servico.dmCategoriaDesc) ?? null,
    msg_pedido: msgPedido ?? null,
    prazo_dia: firstDefined(servico.prazo_dia, servico.prazoDia) == null ? null : Number(firstDefined(servico.prazo_dia, servico.prazoDia)),
    flag_obrigatorio: firstDefined(servico.flag_obrigatorio, servico.flagObrigatorio) ?? null,
    codigo: servico.codigo ?? null,
    dm_estado: firstDefined(servico.dm_estado, servico.dmEstado) ?? null,
    dm_estado_desc: firstDefined(servico.dm_estado_desc, servico.dmEstadoDesc) ?? null,
    id_ent_externa: firstDefined(servico.id_ent_externa, servico.idEntExterna) ?? null,
    possui_taxa: firstDefined(servico.possui_taxa, servico.possuiTaxa) ?? null,
    possui_onboarding: firstDefined(servico.possui_onboarding, servico.possuiOnboarding) ?? null,
    entidade_denominacao: firstDefined(servico.entidade_denominacao, servico.entidadeDenominacao) ?? null,
    entidade_sigla: firstDefined(servico.entidade_sigla, servico.entidadeSigla) ?? null,
    entidade_dm_tipo_ent: firstDefined(servico.entidade_dm_tipo_ent, servico.entidadeDmTipoEnt) ?? null,
    entidade_dm_tipo_ent_desc: firstDefined(servico.entidade_dm_tipo_ent_desc, servico.entidadeDmTipoEntDesc) ?? null,
    quem_deve_solicitar: quemDeveSolicitar,
    tipos_onboarding: tiposOnboarding
  };

  return {
    json: {
      id_tp_solicitacao: id,
      servico,
      strapiPayload: { data }
    }
  };
});

const lookup = $input.first().json;
const original = $('Extrair servicos').item.json;
const data = Array.isArray(lookup.data) ? lookup.data : [];
const existing = data[0];
const existingId = existing?.documentId ?? existing?.id ?? null;

return [{
  json: {
    ...original,
    strapiServicoExiste: Boolean(existingId),
    strapiServicoId: existingId,
    strapiLookup: lookup
  }
}];
